using System.Numerics;
using ByteEngine.Core.Assets;
using ByteEngine.Core.Assets.Importers;
namespace GoblinCombat;
/// <summary>Offline bind-frame retarget bake. Keeps target limb lengths and scales,
/// compensates reference-pose differences, and strips planar pelvis travel.</summary>
public static class HumanoidClipBaker {
 public sealed record Result(ImportedAnimation Clip,int MappedBones,float MaxPlanarTravel,float ScaleRatio);
 public static Result Bake(ModelAsset source,ModelAsset target,ImportedAnimation clip,IReadOnlyDictionary<string,string> sourceToTarget,string name){
  var sn=source.Nodes.ToArray();var tn=target.Nodes.ToArray();var si=sn.Select((n,i)=>(n.Name,i)).GroupBy(x=>x.Name).ToDictionary(g=>g.Key,g=>g.First().i);var ti=tn.Select((n,i)=>(n.Name,i)).GroupBy(x=>x.Name).ToDictionary(g=>g.Key,g=>g.First().i);
  int[] Parents(ImportedNode[] ns){var keys=ns.Select((n,i)=>(n.Key,i)).ToDictionary(x=>x.Key,x=>x.i);return ns.Select(n=>n.ParentKey!=null&&keys.TryGetValue(n.ParentKey,out int p)?p:-1).ToArray();}var sp=Parents(sn);var tp=Parents(tn);
  Matrix4x4[] Globals(Matrix4x4[] locals,int[] parents){var world=new Matrix4x4[locals.Length];var done=new bool[locals.Length];Matrix4x4 Visit(int i){if(!done[i]){world[i]=parents[i]<0?locals[i]:locals[i]*Visit(parents[i]);done[i]=true;}return world[i];}for(int i=0;i<world.Length;i++)Visit(i);return world;}
  Quaternion Rot(Matrix4x4 m){Matrix4x4.Decompose(m,out _,out var q,out _);return Quaternion.Normalize(q);}var sb=Globals(sn.Select(n=>n.LocalTransform).ToArray(),sp);var tb=Globals(tn.Select(n=>n.LocalTransform).ToArray(),tp);
  var map=sourceToTarget.Where(x=>si.ContainsKey(x.Key)&&ti.ContainsKey(x.Value)).ToDictionary(x=>ti[x.Value],x=>si[x.Key]);int Depth(int n){int d=0;while(tp[n]>=0){n=tp[n];d++;}return d;}var order=Enumerable.Range(0,tn.Length).OrderBy(Depth).ToArray();var align=new Dictionary<int,Quaternion>();
  Quaternion Between(Vector3 a,Vector3 b){a=Vector3.Normalize(a);b=Vector3.Normalize(b);float dot=Math.Clamp(Vector3.Dot(a,b),-1,1);if(dot>.99999f)return Quaternion.Identity;if(dot<-.99999f){var axis=Vector3.Cross(a,Vector3.UnitZ);if(axis.LengthSquared()<.01f)axis=Vector3.Cross(a,Vector3.UnitX);return Quaternion.CreateFromAxisAngle(Vector3.Normalize(axis),MathF.PI);}var cross=Vector3.Cross(a,b);return Quaternion.Normalize(new Quaternion(cross,1+dot));}
  foreach(int n in order.Where(map.ContainsKey)){int s=map[n];var children=map.Keys.Where(c=>tp[c]==n).OrderBy(c=>tn[c].Name.Contains("middle")?0:tn[c].Name is "spine" or "chest" or "neck"?0:1).ToArray();Quaternion desiredBind=Rot(tb[n]);if(children.Length>0){int c=children[0],sc=map[c];var targetDir=tb[c].Translation-tb[n].Translation;var sourceDir=sb[sc].Translation-sb[s].Translation;if(targetDir.LengthSquared()>.00001f&&sourceDir.LengthSquared()>.00001f)desiredBind=Quaternion.Normalize(Between(targetDir,sourceDir)*desiredBind);}else if(tp[n]>=0&&align.TryGetValue(tp[n],out var parentAlign)&&map.TryGetValue(tp[n],out int sourceParent)){var parentCorrection=Quaternion.Normalize(Rot(sb[sourceParent])*parentAlign*Quaternion.Inverse(Rot(tb[tp[n]])));desiredBind=Quaternion.Normalize(parentCorrection*desiredBind);}align[n]=Quaternion.Normalize(Quaternion.Inverse(Rot(sb[s]))*desiredBind);}
  int hip=ti["pelvis"],srcHip=si["B-hips"],footL=ti["foot.L"],footR=ti["foot.R"],srcFootL=si["B-foot.L"],srcFootR=si["B-foot.R"];float sourceLeg=sb[srcHip].Translation.Y-(sb[srcFootL].Translation.Y+sb[srcFootR].Translation.Y)*.5f;float targetLeg=tb[hip].Translation.Y-(tb[footL].Translation.Y+tb[footR].Translation.Y)*.5f;float ratio=targetLeg/Math.Max(.01f,sourceLeg);
  Vector3 Sample(ImportedVectorTrack? tr,float t,Vector3 fallback){if(tr==null||tr.Keys.Count==0)return fallback;int k=0;while(k<tr.Keys.Count-2&&tr.Keys[k+1].Time<t)k++;if(tr.Keys.Count==1)return tr.Keys[0].Value;var a=tr.Keys[k];var b=tr.Keys[Math.Min(k+1,tr.Keys.Count-1)];return Vector3.Lerp(a.Value,b.Value,Math.Clamp((t-a.Time)/Math.Max(.000001f,b.Time-a.Time),0,1));}
  Quaternion SampleQ(ImportedQuaternionTrack? tr,float t,Quaternion fallback){if(tr==null||tr.Keys.Count==0)return fallback;int k=0;while(k<tr.Keys.Count-2&&tr.Keys[k+1].Time<t)k++;if(tr.Keys.Count==1)return Quaternion.Normalize(tr.Keys[0].Value);var a=tr.Keys[k];var b=tr.Keys[Math.Min(k+1,tr.Keys.Count-1)];return Quaternion.Normalize(Quaternion.Slerp(a.Value,b.Value,Math.Clamp((t-a.Time)/Math.Max(.000001f,b.Time-a.Time),0,1)));}
  var sourceTracks=clip.Channels.ToDictionary(c=>c.NodeName,c=>c);var rotations=map.Keys.ToDictionary(i=>i,i=>new ImportedQuaternionTrack());var translation=new ImportedVectorTrack();int frames=Math.Max(2,(int)Math.Ceiling(clip.Duration*60));float drift=0;
  for(int f=0;f<=frames;f++){float time=clip.Duration*f/frames;var sl=new Matrix4x4[sn.Length];for(int n=0;n<sn.Length;n++){Matrix4x4.Decompose(sn[n].LocalTransform,out var sc,out var rq,out var pos);if(sourceTracks.TryGetValue(sn[n].Name,out var track)){pos=Sample(track.Translation,time,pos);rq=SampleQ(track.Rotation,time,rq);}sl[n]=Matrix4x4.CreateScale(sc)*Matrix4x4.CreateFromQuaternion(rq)*Matrix4x4.CreateTranslation(pos);}var sg=Globals(sl,sp);var tl=tn.Select(n=>n.LocalTransform).ToArray();var tg=new Matrix4x4[tn.Length];
   foreach(int n in order){Matrix4x4.Decompose(tl[n],out var sc,out var q,out var pos);var parent=tp[n]>=0?tg[tp[n]]:Matrix4x4.Identity;if(map.TryGetValue(n,out int s)){var world=Quaternion.Normalize(Rot(sg[s])*align[n]);q=Quaternion.Normalize(Quaternion.Inverse(Rot(parent))*world);}if(n==hip){var worldPos=tb[hip].Translation;worldPos.Y+=(sg[srcHip].Translation.Y-sb[srcHip].Translation.Y)*ratio;Matrix4x4.Invert(parent,out var inverse);pos=Vector3.Transform(worldPos,inverse);}tl[n]=Matrix4x4.CreateScale(sc)*Matrix4x4.CreateFromQuaternion(q)*Matrix4x4.CreateTranslation(pos);tg[n]=tl[n]*parent;}
   // Match the source's support-foot height without importing its horizontal travel.
   float sourceFeet=Math.Min(sg[srcFootL].Translation.Y,sg[srcFootR].Translation.Y);float sourceRef=Math.Min(sb[srcFootL].Translation.Y,sb[srcFootR].Translation.Y);float targetRef=Math.Min(tb[footL].Translation.Y,tb[footR].Translation.Y);float desiredFoot=targetRef+(sourceFeet-sourceRef)*ratio;float delta=desiredFoot-Math.Min(tg[footL].Translation.Y,tg[footR].Translation.Y);Matrix4x4.Decompose(tl[hip],out var hs,out var hq,out var hp);var parentHip=tp[hip]>=0?tg[tp[hip]]:Matrix4x4.Identity;Matrix4x4.Invert(parentHip,out var inverseHip);var hipWorld=tg[hip].Translation+Vector3.UnitY*delta;hp=Vector3.Transform(hipWorld,inverseHip);translation.Keys.Add(new(time,hp,Vector3.Zero,Vector3.Zero));drift=Math.Max(drift,new Vector2(hipWorld.X-tb[hip].Translation.X,hipWorld.Z-tb[hip].Translation.Z).Length());
   foreach(int n in map.Keys){Matrix4x4.Decompose(tl[n],out _,out var q,out _);q=Quaternion.Normalize(q);if(!float.IsFinite(q.X+q.Y+q.Z+q.W))throw new InvalidDataException("Nonfinite retarget pose");rotations[n].Keys.Add(new(time,q,default,default));}
  }
  var channels=map.Keys.Select(n=>new ImportedAnimationChannel{NodeName=tn[n].Name,Rotation=rotations[n],Translation=n==hip?translation:null}).ToList();return new(new ImportedAnimation{Name=name,Key="manny:"+name,Duration=clip.Duration,Channels=channels},map.Count,drift,ratio);
 }
 public static Dictionary<string,string> HumanMToManny(){var map=new Dictionary<string,string>{{"B-hips","pelvis"},{"B-spine","spine"},{"B-chest","chest"},{"B-neck","neck"},{"B-head","head"}};foreach(string side in new[]{"L","R"}){foreach(var pair in new[]{("shoulder","clavicle"),("upperArm","upper_arm"),("forearm","forearm"),("hand","hand"),("thigh","thigh"),("shin","shin"),("foot","foot"),("toe","toe")})map["B-"+pair.Item1+"."+side]=pair.Item2+"."+side;foreach(string finger in new[]{"index","middle","ring"})for(int i=1;i<=3;i++)map[$"B-{finger}Finger{i:00}.{side}"]=$"{finger}.{i:00}.{side}";for(int i=1;i<=3;i++)map[$"B-pinky{i:00}.{side}"]=$"pinky.{i:00}.{side}";for(int i=1;i<=2;i++)map[$"B-thumb{i:00}.{side}"]=$"thumb.{i:00}.{side}";}return map;}
}

